Here is a production-grade, idiomatic Terraform module implementation that satisfies your canonical scenario and acceptance criteria.

### Directory Structure
```
terraform/
├── modules/
│   └── app-infra/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── main.tf
├── dev.tfvars
└── prod.tfvars
```

---

### `modules/app-infra/variables.tf`
```hcl
variable "environment" {
  description = "Target environment (dev or prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be dev or prod."
  }
}

variable "bucket_name" {
  description = "S3 bucket name"
  type        = string
}

# RDS
variable "db_identifier" {
  description = "RDS instance identifier"
  type        = string
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_master_username" {
  description = "Master username"
  type        = string
  sensitive   = true
}

variable "db_master_password" {
  description = "Master password (must be encrypted in source)"
  type        = string
  sensitive   = true
}

variable "db_subnet_ids" {
  description = "Subnet IDs for RDS"
  type        = list(string)
}

variable "db_multi_az" {
  description = "Enable multi-AZ deployment"
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Enable RDS storage encryption"
  type        = bool
  default     = false
}

# IAM
variable "iam_role_name" {
  description = "Service account role name"
  type        = string
}

variable "iam_trust_principal_type" {
  description = "Principal type: AWS or Federated"
  type        = string
}

variable "iam_trust_principal_arns" {
  description = "List of principal ARNs"
  type        = list(string)
}

variable "iam_oidc_condition" {
  description = "OIDC condition map (used in prod)"
  type        = map(string)
  default     = {}
}

variable "iam_allowed_secret_arns" {
  description = "ARNs of Secrets Manager secrets the role can access"
  type        = list(string)
}

# S3 Replication
variable "enable_cross_region_replication" {
  description = "Enable S3 cross-region replication"
  type        = bool
  default     = false
}

variable "replication_destination_bucket_arn" {
  description = "ARN of the destination bucket for replication"
  type        = string
  default     = ""
}
```

---

### `modules/app-infra/main.tf`
```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

# S3 Bucket
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
  tags   = { Environment = var.environment }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_configuration {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 Cross-Region Replication (Prod)
resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[count.index].arn

  rule {
    status = "Enabled"
    destination {
      bucket = var.replication_destination_bucket_arn
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replication[count.index].arn
      }
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_cross_region_replication ? 1 : 0
  name  = "${var.environment}-s3-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_kms_key" "replication" {
  count = var.enable_cross_region_replication ? 1 : 0
  description = "KMS key for S3 cross-region replication (${var.environment})"
  enable_key_rotation = true
}

# RDS PostgreSQL
resource "aws_db_subnet_group" "this" {
  name       = "${var.db_identifier}-sg"
  subnet_ids = var.db_subnet_ids
  tags       = { Environment = var.environment }
}

resource "aws_db_instance" "this" {
  identifier              = var.db_identifier
  engine                  = "postgres"
  engine_version          = "15.4"
  instance_class          = var.db_instance_class
  username                = var.db_master_username
  password                = var.db_master_password
  db_subnet_group_name    = aws_db_subnet_group.this.name

  publicly_accessible     = false
  deletion_protection     = true
  backup_retention_period = 7
  multi_az                = var.db_multi_az
  storage_encrypted       = var.db_storage_encrypted

  skip_final_snapshot     = true
  copy_tags_to_snapshot   = true

  tags = { Environment = var.environment }
}

# IAM Service Account Role
data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = var.iam_trust_principal_type
      identifiers = var.iam_trust_principal_arns
    }

    dynamic "condition" {
      for_each = length(var.iam_oidc_condition) > 0 ? [var.iam_oidc_condition] : []
      content {
        test     = condition.value.test
        variable = condition.value.variable
        values   = condition.value.values
      }
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = var.iam_role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
  tags               = { Environment = var.environment }
}

# Least-Privilege Policy (No wildcards on prod)
resource "aws_iam_role_policy" "service_account" {
  name = "${var.iam_role_name}-policy"
  role = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3AssetAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
      },
      {
        Sid    = "SecretsAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = var.iam_allowed_secret_arns
      }
    ]
  })
}
```

---

### `modules/app-infra/outputs.tf`
```hcl
output "bucket_arn" {
  description = "ARN of the S3 bucket"
  value       = aws_s3_bucket.this.arn
}

output "db_endpoint" {
  description = "RDS primary endpoint"
  value       = aws_db_instance.this.endpoint
  sensitive   = true
}

output "iam_role_arn" {
  description = "ARN of the service account role"
  value       = aws_iam_role.service_account.arn
}
```

---

### `dev.tfvars`
```hcl
environment    = "dev"
bucket_name    = "myapp-assets-dev-us-east-1"
db_identifier  = "myapp-db-dev"
db_instance_class = "db.t3.micro"
db_multi_az    = false
db_storage_encrypted = false

iam_role_name          = "myapp-service-dev"
iam_trust_principal_type = "AWS"
iam_trust_principal_arns = ["arn:aws:iam::123456789012:user/dev-ci-role"]
iam_allowed_secret_arns = ["arn:aws:secretsmanager:us-east-1:123456789012:secret:myapp/db-conn-*"]

enable_cross_region_replication = false
```

---

### `prod.tfvars`
```hcl
environment    = "prod"
bucket_name    = "myapp-assets-prod-us-east-1"
db_identifier  = "myapp-db-prod"
db_instance_class = "db.t3.medium"
db_multi_az    = true
db_storage_encrypted = true

iam_role_name          = "myapp-service-prod"
iam_trust_principal_type = "Federated"
iam_trust_principal_arns = ["arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/ABCD1234"]
iam_oidc_condition = {
  test     = "StringEquals"
  variable = "oidc.eks.us-east-1.amazonaws.com/id/ABCD1234:sub"
  values   = ["system:serviceaccount:prod-ns:myapp-sa"]
}
iam_allowed_secret_arns = [
  "arn:aws:secretsmanager:us-east-1:123456789012:secret:myapp/db-conn-prod"
]

enable_cross_region_replication = true
replication_destination_bucket_arn = "arn:aws:s3:::myapp-assets-prod-us-west-2"
```

---

### `main.tf` (Root)
```hcl
terraform {
  backend "s3" {
    bucket = "terraform-state-myapp"
    key    = "infra/${var.environment}/terraform.tfstate"
    region = "us-east-1"
    encrypt = true
  }

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = {
      Project     = "myapp"
      ManagedBy   = "terraform"
      Environment = var.environment
    }
  }
}

variable "environment" { type = string }
variable "db_master_username" { type = string; sensitive = true }
variable "db_master_password" { type = string; sensitive = true }
variable "db_subnet_ids" { type = list(string) }

module "app_infra" {
  source = "./modules/app-infra"

  environment    = var.environment
  bucket_name    = var.bucket_name
  db_identifier  = var.db_identifier
  db_instance_class = var.db_instance_class
  db_master_username = var.db_master_username
